CREATE TABLE IF NOT EXISTS attendance_employee_settings(employee_id uuid PRIMARY KEY REFERENCES employees(id) ON DELETE CASCADE,device_code text UNIQUE,late_grace_minutes integer NOT NULL DEFAULT 10 CHECK(late_grace_minutes BETWEEN 0 AND 240),early_grace_minutes integer NOT NULL DEFAULT 5 CHECK(early_grace_minutes BETWEEN 0 AND 240),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_weekly_schedule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES employees(id) ON DELETE CASCADE,weekday smallint NOT NULL CHECK(weekday BETWEEN 0 AND 6),starts_at time,ends_at time,is_day_off boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,weekday),CHECK(is_day_off OR (starts_at IS NOT NULL AND ends_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS attendance_schedule_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES employees(id) ON DELETE CASCADE,start_date date NOT NULL,end_date date NOT NULL,starts_at time,ends_at time,is_day_off boolean NOT NULL DEFAULT false,note text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>=start_date),CHECK(is_day_off OR (starts_at IS NOT NULL AND ends_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS attendance_import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_name text NOT NULL,imported_by uuid REFERENCES users(id),total_rows integer NOT NULL DEFAULT 0,inserted_rows integer NOT NULL DEFAULT 0,duplicate_rows integer NOT NULL DEFAULT 0,suspicious_rows integer NOT NULL DEFAULT 0,unknown_rows integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_punches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid REFERENCES attendance_import_batches(id),employee_id uuid REFERENCES employees(id),device_code text NOT NULL,punch_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'UNKNOWN',verify_method text NOT NULL DEFAULT 'UNKNOWN' CHECK(verify_method IN ('FINGERPRINT','PASSWORD','CARD','UNKNOWN')),location_id text,id_number text,card_no text,suspicious boolean NOT NULL DEFAULT false,duplicate_of uuid REFERENCES attendance_punches(id),review_status text NOT NULL DEFAULT 'PENDING' CHECK(review_status IN ('PENDING','APPROVED','REJECTED')),raw_record jsonb NOT NULL DEFAULT '{}'::jsonb,external_key text NOT NULL UNIQUE,reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS attendance_punches_employee_time_idx ON attendance_punches(employee_id,punch_at DESC);
CREATE INDEX IF NOT EXISTS attendance_punches_review_idx ON attendance_punches(review_status,suspicious,punch_at DESC);
CREATE INDEX IF NOT EXISTS attendance_punches_batch_idx ON attendance_punches(batch_id);
INSERT INTO permissions(code,module,entity,action,scope) VALUES('attendance.view','attendance','attendance','view','all'),('attendance.import','attendance','attendance','import','all'),('attendance.manage','attendance','attendance','manage','all'),('attendance.review','attendance','attendance','review','all') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN ('manager','admin','hr') AND p.code LIKE 'attendance.%' ON CONFLICT DO NOTHING;
INSERT INTO schema_migrations(version) VALUES('1037_attendance_foundation') ON CONFLICT(version) DO NOTHING;